for a,b in list(PHRASES.items()):
    if html.escape(a)!=a: PHRASES[html.escape(a)]=html.escape(b)
THAI=re.compile('[\u0e00-\u0e7f]')
PATTERN=re.compile('(?<![\u0e00-\u0e7f])(?:'+'|'.join(re.escape(k) for k in sorted(PHRASES,key=len,reverse=True))+')(?![\u0e00-\u0e7f])')
UNTRANSLATED=set()
@lru_cache(maxsize=50000)
def english(value):
    if not isinstance(value,str) or not THAI.search(value): return value
    result=PHRASES.get(value)
    if result is None: result=PATTERN.sub(lambda m:PHRASES[m.group()],value)
    if THAI.search(result):
        # Store unresolved display text for offline QA; never hide it or guess a label.
        UNTRANSLATED.add(result)
    return result

def display_frame(value):
    if isinstance(value,pd.Series): return value.map(lambda x:english(x) if isinstance(x,str) else x)
    if not isinstance(value,pd.DataFrame): return value
    view=value.copy()
    view.columns=[english(x) if isinstance(x,str) else x for x in view.columns]
    if view.index.dtype=='object': view.index=view.index.map(lambda x:english(x) if isinstance(x,str) else x)
    for col in view.select_dtypes(include=['object','string']):
        view[col]=view[col].map(lambda x:english(x) if isinstance(x,str) else x)
    return view

def _tree(v):
    if isinstance(v,str): return english(v)
    if isinstance(v,dict): return {k:_tree(x) for k,x in v.items()}
    if isinstance(v,(tuple,list)): return [_tree(x) for x in v]
    if hasattr(v,'dtype') and v.dtype.kind in 'OU':
        return [_tree(x) for x in v.tolist()]
    return v

def install(st):
    from streamlit.delta_generator import DeltaGenerator
    if getattr(DeltaGenerator,'_burnwise_english',False): return
    def wrap(original,name,has_self=False):
        @wraps(original)
        def wrapped(*args,**kwargs):
            args=list(args); first=1 if has_self else 0
            if len(args)>first:
                if name in ('dataframe','table'): args[first]=display_frame(args[first])
                elif name=='plotly_chart':
                    import plotly.graph_objects as go
                    if hasattr(args[first],'to_plotly_json'): args[first]=go.Figure(_tree(args[first].to_plotly_json()))
                elif isinstance(args[first],str): args[first]=english(args[first])
                elif name=='write': args[first]=display_frame(args[first])
            if name=='write':
                args[first:]=[english(x) if isinstance(x,str) else display_frame(x) for x in args[first:]]
            for key in ('label','help','placeholder','title','text','body','caption'):
                if isinstance(kwargs.get(key),str): kwargs[key]=english(kwargs[key])
            if name in ('radio','selectbox','multiselect','select_slider'):
                fmt=kwargs.get('format_func',str)
                kwargs['format_func']=lambda value:english(str(fmt(value)))
            if 'column_config' in kwargs:
                kwargs['column_config']={k:english(v) if isinstance(v,str) else v for k,v in kwargs['column_config'].items()}
            return original(*args,**kwargs)
        return wrapped
    names=('markdown','html','caption','write','text','title','header','subheader','info','warning','error','success','toast','metric','button','download_button','checkbox','toggle','radio','selectbox','multiselect','select_slider','slider','text_input','text_area','file_uploader','expander','popover','spinner','dataframe','table','plotly_chart')
    for name in names:
        if hasattr(st,name): setattr(st,name,wrap(getattr(st,name),name))
        if hasattr(DeltaGenerator,name): setattr(DeltaGenerator,name,wrap(getattr(DeltaGenerator,name),name,True))
    DeltaGenerator._burnwise_english=True
